package com.eugenia.orders.domain;
import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.List; import static com.eugenia.orders.domain.OrderModels.*; import static org.assertj.core.api.Assertions.*;
class OrderCalculatorTest { private final OrderCalculator c=new OrderCalculator(); private Item item(String id,int q,String p,TaxCategory t){return new Item(id,q,new BigDecimal(p),t);} @Test void taxMatrix(){assertThat(c.taxRate(Market.MX,TaxRegime.GENERAL,TaxCategory.STANDARD)).isEqualByComparingTo("0.16");assertThat(c.taxRate(Market.CO,TaxRegime.GENERAL,TaxCategory.REDUCED)).isEqualByComparingTo("0.05");assertThat(c.taxRate(Market.PE,TaxRegime.GENERAL,TaxCategory.STANDARD)).isEqualByComparingTo("0.18");} @Test void exemption(){assertThat(c.calculate(Market.MX,TaxRegime.EXEMPT,Segment.RETAIL,List.of(item("A",1,"10",TaxCategory.STANDARD))).totals().tax()).isEqualByComparingTo("0.00");} @Test void wholesaleDiscount(){assertThat(c.calculate(Market.MX,TaxRegime.GENERAL,Segment.WHOLESALE,List.of(item("A",20,"10",TaxCategory.EXEMPT))).totals().grandTotal()).isEqualByComparingTo("194.00");} @Test void roundsLinesBeforeAggregation(){var r=c.calculate(Market.MX,TaxRegime.GENERAL,Segment.RETAIL,List.of(item("A",1,"0.05",TaxCategory.STANDARD),item("B",1,"0.05",TaxCategory.STANDARD)));assertThat(r.totals().tax()).isEqualByComparingTo("0.02");assertThat(r.totals().grandTotal()).isEqualByComparingTo("0.12");} }
